<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\User\Action\Command;

use Module\User\Action\Command\ValidateAccessTokenCmd;
use Module\User\Support\TokenService;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Component\Security\Core\Exception\BadCredentialsException;
use Tests\UnitTestCase;

class ValidateAccessTokenCmdTest extends UnitTestCase
{
    private ValidateAccessTokenCmd $sut;

    public function setUp(): void
    {
        parent::setUp();

        $tokenService = $this->createStub(TokenService::class);
        $tokenService->method('validateToken')->willReturnCallback(function (string $token): string {
            if ($token === 'valid-token') {
                return 'user@example.com';
            }
            throw new BadCredentialsException('Invalid token.');
        });

        $this->sut = new ValidateAccessTokenCmd($tokenService);
    }

    #[Test, DataProvider('dataProviderGetUserBadgeFrom')]
    public function getUserBadgeFrom(
        string $accessToken,
        string $expectedIdentifier,
        bool $expectedException,
    ): void {
        if ($expectedException) {
            $this->expectException(BadCredentialsException::class);
        }

        $result = $this->sut->getUserBadgeFrom($accessToken);

        $this->assertSame($expectedIdentifier, $result->getUserIdentifier());
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderGetUserBadgeFrom(): array
    {
        return [
            'success' => [
                'accessToken' => 'valid-token',
                'expectedIdentifier' => 'user@example.com',
                'expectedException' => false,
            ],
            'invalid token' => [
                'accessToken' => 'bad-token',
                'expectedIdentifier' => '',
                'expectedException' => true,
            ],
        ];
    }
}
